def run(cmd):
    print('+', ' '.join(map(str,cmd)), flush=True)
    subprocess.run(list(map(str,cmd)), check=True)

def ffprobe_duration(p):
    return float(subprocess.check_output(['ffprobe','-v','error','-show_entries','format=duration','-of','default=nw=1:nk=1',str(p)]).decode().strip())

def rtl_safe_numbers(text):
    # Keep numeric ranges/fractions left-to-right inside Hebrew RTL text.
    pattern = r'([0-9]+[½¼¾]?(?:[–-][0-9]+[½¼¾]?)?(?:°)?)'
    return re.sub(pattern, lambda m: '\u2066' + m.group(1) + '\u2069', text)

def fit_lines(draw, text, font, maxw, max_lines=3):
    text = rtl_safe_numbers(text)
    words=text.split(); lines=[]; cur=''
    for w in words:
        test=(cur+' '+w).strip()
        if draw.textbbox((0,0),test,font=font,direction='rtl')[2] <= maxw:
            cur=test
        else:
            if cur: lines.append(cur)
            cur=w
    if cur: lines.append(cur)
    if len(lines)>max_lines:
        lines=lines[:max_lines]; lines[-1]=lines[-1].rstrip('.,')+'…'
    return lines

def bread_icon(draw,cx,cy,s):
    box=(cx-s,cy-s*0.55,cx+s,cy+s*0.55)
    draw.ellipse(box,fill='#D79A55',outline='#8B5732',width=max(2,int(s*.025)))
    for dx in (-.42,0,.42):
        x=cx+dx*s; draw.arc((x-s*.22,cy-s*.34,x+s*.22,cy+s*.18),195,340,fill='#F5D39A',width=max(2,int(s*.03)))

def draw_scene(scene, idx, total, size, outpath, vertical=False):
    W,H=size; im=Image.new('RGB',size,PALETTE['bg']); d=ImageDraw.Draw(im)
    pad=int(W*.07); top=int(H*.065)
    d.rounded_rectangle((pad,top,W-pad,top+int(H*.045)),radius=20,fill='#E2E8DB')
    pw=int((W-2*pad)*(idx/total)); d.rounded_rectangle((pad,top,pad+pw,top+int(H*.045)),radius=20,fill=PALETTE['green'])
    step,title,bullets,narr=scene
    small=ImageFont.truetype(FONT_B, int(W*(.025 if not vertical else .036)))
    titlef=ImageFont.truetype(FONT_B, int(W*(.05 if not vertical else .07)))
    bulletf=ImageFont.truetype(FONT, int(W*(.026 if not vertical else .043)))
    d.text((W-pad, top+int(H*.075)), step, font=small, fill=PALETTE['terracotta'], anchor='ra', direction='rtl')
    y=top+int(H*.14)
    for line in fit_lines(d,title,titlef,W-2*pad,3):
        d.text((W-pad,y),line,font=titlef,fill=PALETTE['green'],anchor='ra',direction='rtl'); y += int(titlef.size*1.18)
    icon_y=int(H*(.50 if vertical else .56)); icon_s=int(min(W,H)*(.16 if vertical else .13))
    d.rounded_rectangle((pad, icon_y-icon_s*1.25, pad+icon_s*2.5, icon_y+icon_s*1.25), radius=28, fill=PALETTE['cream'], outline='#DED6C6', width=3)
    bread_icon(d,pad+int(icon_s*1.25),icon_y,icon_s*.75)
    bx1=pad+int(icon_s*2.85); bx2=W-pad; by1=icon_y-int(icon_s*1.25); by2=icon_y+int(icon_s*1.25)
    if vertical:
        bx1=pad; by1=icon_y+int(icon_s*1.55); bx2=W-pad; by2=min(H-pad, by1+int(H*.23))
    d.rounded_rectangle((bx1,by1,bx2,by2),radius=28,fill='#FFFFFF',outline='#DED6C6',width=3)
    yy=by1+int(H*.025)
    for b in bullets:
        for j,line in enumerate(fit_lines(d,b,bulletf,bx2-bx1-int(W*.07),2)):
            prefix='- ' if j==0 else '  '
            d.text((bx2-int(W*.025),yy),prefix+line,font=bulletf,fill=PALETTE['text'],anchor='ra',direction='rtl'); yy += int(bulletf.size*1.35)
        yy += int(bulletf.size*.15)
    foot=ImageFont.truetype(FONT,int(W*(.018 if not vertical else .03)))
    d.text((W-pad,H-int(H*.045)),'סלוף תימני בבית | מדריך מלא ומעשי',font=foot,fill=PALETTE['muted'],anchor='rs',direction='rtl')
    im.save(outpath,quality=95)

async def tts(text,path):
    c=edge_tts.Communicate(text, VOICE, rate=RATE, volume='+0%')
    await c.save(str(path))

async def render_set(scenes,name,size):
    vertical=size[1]>size[0]
    base=OUT/name; (base/'img').mkdir(parents=True,exist_ok=True); (base/'audio').mkdir(exist_ok=True); (base/'seg').mkdir(exist_ok=True)
    for i,sc in enumerate(scenes,1):
        img=base/'img'/f'{i:03d}.png'; aud=base/'audio'/f'{i:03d}.mp3'; seg=base/'seg'/f'{i:03d}.mp4'
        draw_scene(sc,i,len(scenes),size,img,vertical)
        print('TTS',i,sc[1],flush=True); await tts(sc[3],aud)
        dur=ffprobe_duration(aud)+0.65; fps=25
        vf=f"scale={size[0]}:{size[1]},zoompan=z='min(zoom+0.00018,1.025)':d=1:s={size[0]}x{size[1]}:fps={fps},format=yuv420p"
        run(['ffmpeg','-y','-loglevel','error','-loop','1','-i',img,'-i',aud,'-t',f'{dur:.3f}','-vf',vf,'-c:v','libx264','-preset','veryfast','-crf','20','-r',str(fps),'-c:a','aac','-b:a','160k','-ar','48000','-ac','2','-shortest',seg])
    lst=base/'concat.txt'; lst.write_text('\n'.join([f"file '{(base/'seg'/f'{i:03d}.mp4').resolve()}'" for i in range(1,len(scenes)+1)]),encoding='utf-8')
    tmp=OUT/f'{name}_tmp.mp4'; final=OUT/f'{name}.mp4'
    run(['ffmpeg','-y','-loglevel','error','-f','concat','-safe','0','-i',lst,'-c','copy',tmp])
    run(['ffmpeg','-y','-loglevel','error','-i',tmp,'-c:v','copy','-af','loudnorm=I=-16:LRA=8:TP=-1.5','-c:a','aac','-b:a','160k','-movflags','+faststart',final])
    print('DONE',final,ffprobe_duration(final)); return final

async def main():
    full=await render_set(FULL,'Saluf_Master_Full_HE_1080p',(1920,1080))
    tik=await render_set(TIK,'Saluf_TikTok_HE_1080x1920',(1080,1920))
    for p in (full,tik):
        print(subprocess.check_output(['ffprobe','-v','error','-show_entries','stream=index,codec_type,codec_name:format=duration','-of','json',str(p)]).decode())

if __name__=='__main__': asyncio.run(main())
